1	export type ScheduledReminderPrompt = {
2	  reminderText: string;
3	  currentTime?: string;
4	};
5	
6	const SCHEDULED_REMINDER_PREFIX = 'A scheduled reminder has been triggered. The reminder content is:';
7	const SCHEDULED_REMINDER_INTERNAL_INSTRUCTION = 'Handle this reminder internally. Do not relay it to the user unless explicitly requested.';
8	const SCHEDULED_REMINDER_RELAY_INSTRUCTION = 'Please relay this reminder to the user in a helpful and friendly way.';
9	const CURRENT_TIME_PREFIX = 'Current time:';
10	const LEGACY_SYSTEM_LINE_RE = /^System:\s*(?:\[(.+?)\]\s*)?(⏰.+)$/u;
11	const SIMPLE_REMINDER_RE = /^⏰(?:\s|$)/u;
12	
13	export function parseScheduledReminderPrompt(text: string): ScheduledReminderPrompt | null {
14	  const trimmed = text.trim();
15	  if (!trimmed.startsWith(SCHEDULED_REMINDER_PREFIX)) {
16	    return null;
17	  }
18	
19	  let remainder = trimmed.slice(SCHEDULED_REMINDER_PREFIX.length).trim();
20	  let currentTime: string | undefined;
21	  const currentTimeIndex = remainder.lastIndexOf(CURRENT_TIME_PREFIX);
22	  if (currentTimeIndex >= 0) {
23	    currentTime = remainder.slice(currentTimeIndex + CURRENT_TIME_PREFIX.length).trim() || undefined;
24	    remainder = remainder.slice(0, currentTimeIndex).trim();
25	  }
26	
27	  if (remainder.endsWith(SCHEDULED_REMINDER_INTERNAL_INSTRUCTION)) {
28	    remainder = remainder.slice(0, -SCHEDULED_REMINDER_INTERNAL_INSTRUCTION.length).trim();
29	  } else if (remainder.endsWith(SCHEDULED_REMINDER_RELAY_INSTRUCTION)) {
30	    remainder = remainder.slice(0, -SCHEDULED_REMINDER_RELAY_INSTRUCTION.length).trim();
31	  }
32	
33	  if (!remainder) {
34	    return null;
35	  }
36	
37	  return {
38	    reminderText: remainder,
39	    ...(currentTime ? { currentTime } : {}),
40	  };
41	}
42	
43	export function parseLegacyScheduledReminderSystemMessage(text: string): ScheduledReminderPrompt | null {
44	  const trimmed = text.trim();
45	  const firstLine = trimmed.split(/\r?\n/u, 1)[0]?.trim() ?? '';
46	  const match = firstLine.match(LEGACY_SYSTEM_LINE_RE);
47	  if (!match) {
48	    return null;
49	  }
50	
51	  const rest = trimmed.slice(firstLine.length).trim();
52	  const wrappedPrompt = rest ? parseScheduledReminderPrompt(rest) : null;
53	
54	  return wrappedPrompt ?? {
55	    reminderText: match[2].trim(),
56	    ...(match[1]?.trim() ? { currentTime: match[1].trim() } : {}),
57	  };
58	}
59	
60	export function isSimpleScheduledReminderText(text: string): boolean {
61	  return SIMPLE_REMINDER_RE.test(text.trim());
62	}
63	
64	export function parseSimpleScheduledReminderText(text: string): ScheduledReminderPrompt | null {
65	  const trimmed = text.trim();
66	  if (!isSimpleScheduledReminderText(trimmed)) {
67	    return null;
68	  }
69	
70	  return {
71	    reminderText: trimmed,
72	  };
73	}
74	
75	export function getScheduledReminderDisplayText(text: string): string | null {
76	  const prompt = parseScheduledReminderPrompt(text);
77	  if (prompt) {
78	    return prompt.reminderText;
79	  }
80	
81	  const legacy = parseLegacyScheduledReminderSystemMessage(text);
82	  if (legacy) {
83	    return legacy.reminderText;
84	  }
85	
86	  const simple = parseSimpleScheduledReminderText(text);
87	  if (simple) {
88	    return simple.reminderText;
89	  }
90	
91	  return null;
92	}
